  "about": "우리나라 사람 대부분이 쓰는 메신저 카카오톡을 만든 회사예요. 카카오톡 안의 광고와 선물하기로 돈을 벌고, 택시 호출(카카오모빌리티)·간편결제(카카오페이) 같은 서비스와 음악(멜론, SM엔터테인먼트)·웹툰·게임 같은 콘텐츠 사업도 해요. 2025년 매출 8조 991억 원, 영업이익 7,320억 원으로 역대 최대 실적을 냈어요.",
