  "about": "1968년 국영 기업으로 출발한 포항종합제철(포스코)이 2022년 지주회사로 바뀌면서 생긴 회사예요. 포항·광양 제철소를 가진 철강 회사 포스코를 중심으로, 리튬·니켈·양극재 같은 이차전지 소재와 무역·건설(포스코인터내셔널·포스코이앤씨) 회사를 거느리고 있어요. 2025년 매출은 약 69조 원이었어요.",
